using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: JsonTypeInfo<T>
JsonTypeInfo<Person> typedInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Typed info for Person — Type: {typedInfo.Type.Name}, Kind: {typedInfo.Kind}");

// 2) Probe without throwing using TryGetTypeInfo
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, kind={probed?.Kind}");

// Probe a type whose resolver intentionally doesn't handle it
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

bool foundOrder = limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo);
Console.WriteLine($"TryGetTypeInfo(Order) on limited resolver: found={foundOrder}, info={orderInfo?.Type.Name ?? "(null)"}");

// Models
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// A resolver that only handles Person, not Order
file class LimitedResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signal "not available"
    }
}

